      // Minimal observable contract
    function publishState() {
      window.__game = {
        state: 'menu',
        score: 0,
        player: {
          x: canvas.width / 2,
          y: canvas.height / 2,
          visible: true,
        },
        objective: 'Tap to compress the tunnel and guide the dot through gaps.',
      };
    }

    // === RESET ==============================================================
    function reset() {
      // Reset any state here (none for now)
      publishState();
      startLoop();
    }

    // === LOOP ===============================================================
    function startLoop() {
      if (loopId !== null) cancelAnimationFrame(loopId);
      function tick(now) {
        try {
          const dt = Math.min((now - lastTime) / 1000, 0.1);
          lastTime = now;
          update(dt);
          render();
          publishState();
        } catch (e) {
          console.error('loop error', e);
        }
        loopId = requestAnimationFrame(tick);
      }
      loopId = requestAnimationFrame(tick);
    }

    // === UPDATE ==============================================================
    function update(dt) {
      // No game logic yet
    }

    // === RENDER ==============================================================
    function render() {
      ctx.fillStyle = '#0f1320';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      // Simple dot to ensure canvas is not blank
      ctx.fillStyle = '#7df9ff';
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, 5, 0, Math.PI * 2);
      ctx.fill();
    }

    // === INPUT ===============================================================
    document.addEventListener('keydown', ev => {
      if (ev.key === 'r' || ev.key === 'R') {
        reset();
        return;
      }
      keys.add(ev.key);
    });
    document.addEventListener('keyup', ev => {
      keys.delete(ev.key);
    });
    restartBtn.addEventListener('click', reset);

    // === AUDIO (lazy) =======================================================
    function beep(freq, durSec) {
      try {
        if (!window.audioCtx) window.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = window.audioCtx.createOscillator();
        const gain = window.audioCtx.createGain();
        osc.type = 'square';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.05, window.audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, window.audioCtx.currentTime + durSec);
        osc.connect(gain);
        gain.connect(window.audioCtx.destination);
        osc.start();
        osc.stop(window.audioCtx.currentTime + durSec);
      } catch (e) {}
    }

    // === BOOT ===============================================================
    reset();
```

